<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { openUpgrade } from '../lib/premium.js'
import { Plus, X, Globe, Phone, Store, RefreshCw } from 'lucide-vue-next'
import { apiFetch } from '../lib/api.js'
import { loadReferenceData } from '../lib/referenceData.js'
import { createProgram, updateProgram, firstError, setProgramState } from '../lib/subscriptions.js'
import { useCurrentUser } from '../lib/currentUser.js'
import { CAP } from '../lib/permissions.js'
import { uploadImage } from '../lib/imageUpload.js'
const props = defineProps({ embedded: Boolean }), emit = defineEmits(['saved'])
const { can } = useCurrentUser(), manage = computed(() => can(CAP.MANAGE_LISTINGS))
const rows = ref([]), venues = ref([]), loading = ref(true), busy = ref(false), error = ref(''), message = ref(''), billingEnabled = ref(false), billingDisabledReason = ref('')
const route = useRoute()
const query = ref(''), placement = ref('all'), tab = ref(route.query.tab === 'billing' ? 'billing' : 'listings'), editor = ref(false), editTab = ref('details'), form = ref({}), original = ref(''), discard = ref(false), selectedId = ref(null), confirmation = ref(null)
const selected = computed(() => rows.value.find(p => p.id === selectedId.value))
const filtered = computed(() => rows.value.filter(p => `${p.name} ${p.venue_name} ${p.business_name}`.toLowerCase().includes(query.value.toLowerCase()) && (placement.value === 'all' || placement.value === 'marketplace' && p.marketplace_live || placement.value === 'website' && p.website_live || placement.value === 'hidden' && !p.marketplace_live && !p.website_live)))
const billFrom = ref(''), billTo = ref('')
const invoices = computed(() => filtered.value.flatMap(p => (p.listing_invoices || []).map(i => ({ ...i, listing: p.name, business: p.business_name }))).filter(i => (!billFrom.value || (i.paid_at || i.created_at || '').slice(0,10) >= billFrom.value) && (!billTo.value || (i.paid_at || i.created_at || '').slice(0,10) <= billTo.value)).sort((a,b) => b.id-a.id))
const received = computed(() => invoices.value.reduce((n,i) => n + (i.status === 'paid' ? Number(i.amount_paid) - Number(i.amount_refunded || 0) : 0), 0))
const money = n => `USD ${Number(n || 0).toFixed(2)}`
const date = d => d ? new Date(d).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }) : '—'
const safeLink = url => /^https?:\/\//i.test(url || '') ? url : null
const current = computed(() => rows.value.find(p => p.id === form.value.id))
const venue = computed(() => venues.value.find(v => String(v.id) === String(form.value.location_id)))
const websiteAllowed = computed(() => current.value?.website_entitled === true && String(current.value.location_id) === String(form.value.location_id))
function status(p) { return p.is_draft ? 'Draft' : ['paused','ineligible'].includes(p.eligibility_status) ? 'Paused by Bookboll' : p.approval_status === 'rejected' ? 'Changes required' : p.status !== 'active' ? 'Hidden' : p.approval_status === 'pending' || p.pending_content ? 'Awaiting review' : p.marketplace_live ? 'Live' : 'Payment required' }
async function load() {
  loading.value = true; error.value = ''
  try { const [res, refs] = await Promise.all([apiFetch('/admin/membership-listings'), loadReferenceData()]); if (!res.success) throw new Error(firstError(res)); rows.value = res.data.programs || []; billingEnabled.value = res.data.billing_enabled; billingDisabledReason.value = res.data.billing_disabled_reason; venues.value = refs.venues }
  catch(e) { error.value = e.message } finally { loading.value = false }
}
onMounted(async () => { await load(); if (route.query.new === '1' && manage.value) openNewProgram() })
function openEditProgram(p) {
  form.value = { name: '', location_id: '', description: '', contact_phone: '', schedule_description: '', sport_category: '', coach_name: '', monthly_price: 0, currency: 'QAR', billing_interval: 'monthly', photo_url: '', images: [], status: 'active', category: 'academy', audience: 'all', gender_policy: 'all', is_draft: false, show_on_marketplace: true, show_on_provider_site: false, ...p }
  original.value = JSON.stringify(form.value); editor.value = true; editTab.value = 'details'; error.value = ''; discard.value = false
}
function openNewProgram(locationId) { openEditProgram({ location_id: locationId || '' }) }
function openDuplicateProgram(p) { openEditProgram({ ...p, id: null, uuid: null, name: `${p.name} (copy)`, is_draft: true, show_on_provider_site: false, listing_subscription: null, listing_invoices: [] }) }
defineExpose({ openNewProgram, openEditProgram, openDuplicateProgram })
function close() { if (busy.value) return; if (original.value !== JSON.stringify(form.value)) discard.value = true; else editor.value = false }
function closeBilling() { if (!busy.value) { selectedId.value = null; confirmation.value = null } }
function chooseVenue() { if (venue.value?.phone && !form.value.contact_phone) form.value.contact_phone = venue.value.phone; form.value.show_on_provider_site = false }
async function save(draft = false) {
  if (busy.value || !manage.value) return
  busy.value = true; error.value = ''
  try {
    const payload = { ...form.value, is_draft: draft, status: draft ? 'inactive' : 'active', monthly_price: Number(form.value.monthly_price || 0), location_id: form.value.location_id || null }
    const res = form.value.id ? await updateProgram(form.value.id, payload) : await createProgram(payload)
    if (!res.success) throw new Error(firstError(res))
    message.value = draft ? 'Draft saved.' : 'Listing saved. Check its placement status before sharing.'; editor.value = false; await load(); emit('saved')
  } catch(e) { error.value = e.message } finally { busy.value = false }
}
async function upload(event) {
  const file = event.target.files?.[0]; if (!file) return
  busy.value = true; const res = await uploadImage(file, 'memberships'); busy.value = false
  if (res.error) error.value = res.error; else { form.value.photo_url = res.url; form.value.images = [res.url, ...(form.value.images || []).filter(x => x !== res.url)].slice(0,12) }
}
async function billing(action) {
  const p = selected.value; if (!p || busy.value) return
  busy.value = true; error.value = ''
  try {
    const res = await apiFetch(`/admin/membership-listings/${p.id}/${action === 'checkout' ? 'checkout' : 'billing'}`, { method: 'POST', body: action === 'checkout' ? {} : { action } })
    if (!res.success) throw new Error(firstError(res))
    if (res.data.url && safeLink(res.data.url)) window.location.assign(res.data.url)
    else { confirmation.value = null; await load(); message.value = 'Renewal updated.' }
  } catch(e) { error.value = e.message } finally { busy.value = false }
}
async function toggle(p) {
  busy.value = true
  try { const res = await setProgramState(p.id, { status: p.status === 'active' ? 'inactive' : 'active' }); if (!res.success) throw new Error(firstError(res)); await load(); emit('saved') } catch(e) { error.value = e.message } finally { busy.value = false }
}
</script>
<template>
  <div v-if="!embedded" class="page ml-page">
    <header class="ml-header"><div><h1>Membership listings</h1><p>Help customers discover your academy. They contact you to enrol and pay directly.</p></div><button v-if="manage" class="btn btn-primary" @click="openNewProgram()"><Plus :size="16"/> Add membership listing</button></header>
    <div class="ml-model"><section><Globe :size="22"/><div><strong>Bookboll marketplace</strong><p>A monthly subscription for each listing, on every plan. Default USD 20; your venue’s local rate applies.</p></div></section><section><Store :size="22"/><div><strong>Your own website</strong><p>Membership listings are included with Premium. Marketplace subscriptions are purchased separately.</p></div></section></div>
    <nav class="ml-tabs" aria-label="Membership management"><button :class="{active:tab==='listings'}" @click="tab='listings'">Listings · {{ rows.length }}</button><button :class="{active:tab==='billing'}" @click="tab='billing'">Listing payments</button></nav>
    <div class="ml-toolbar"><input v-model="query" type="search" aria-label="Search membership listings" placeholder="Search listing, venue or business…"/><select v-model="placement" aria-label="Listing placement"><option value="all">All placements</option><option value="marketplace">Live on marketplace</option><option value="website">Live on own website</option><option value="hidden">Not visible</option></select><button class="btn btn-secondary" :disabled="loading" @click="load"><RefreshCw :size="15"/> Refresh</button></div>
    <p v-if="message" class="ml-notice" role="status">{{ message }}</p><p v-if="error && !editor && !selected" class="ml-error" role="alert">{{ error }}</p>
    <p v-if="loading" class="ml-empty">Loading membership listings…</p>
    <template v-else-if="tab==='listings'">
      <div v-if="!filtered.length" class="ml-empty"><h2>{{ rows.length ? 'No matching listings' : 'Let customers find your academy' }}</h2><p>Add your programme, contact phone and photos. Then choose where it appears.</p><button v-if="manage && !rows.length" class="btn btn-primary" @click="openNewProgram()">Create your first listing</button></div>
      <article v-for="p in filtered" :key="p.id" class="ml-listing">
        <div class="ml-identity"><img v-if="safeLink(p.photo_url)" :src="p.photo_url" alt=""/><div v-else class="ml-placeholder"><Store :size="24"/></div><div><h2>{{ p.name }}</h2><p>{{ p.business_name }} · {{ p.venue_name || 'Choose a venue' }}</p><small><Phone :size="12"/> {{ p.contact_phone || 'Add a contact phone' }}</small></div></div>
        <div class="ml-placement"><span>Marketplace</span><strong :class="{live:p.marketplace_live}">{{ !p.show_on_marketplace ? 'Not selected' : status(p) }}</strong><small>{{ money(p.listing_subscription?.amount ?? p.listing_monthly_price) }} / month</small></div>
        <div class="ml-placement"><span>Own website</span><strong :class="{live:p.website_live}">{{ !p.website_entitled ? 'Premium required' : p.website_live ? 'Live' : 'Not visible' }}</strong><small>{{ p.website_entitled ? 'Included in Premium' : 'Upgrade the business plan' }}</small></div>
        <div class="ml-actions"><button class="btn btn-secondary btn-sm" @click="selectedId=p.id; confirmation=null; error=''">View billing</button><button v-if="manage" class="btn btn-primary btn-sm" @click="openEditProgram(p)">Edit listing</button></div>
      </article>
    </template>
    <section v-else class="ml-billing"><div class="ml-toolbar" style="padding:0 24px"><label>From<input v-model="billFrom" type="date" :max="billTo || undefined"/></label><label>To<input v-model="billTo" type="date" :min="billFrom || undefined"/></label><button class="btn btn-secondary" @click="billFrom='';billTo=''">All dates</button></div><div class="ml-billing-head"><div><h2>Marketplace listing payments</h2><p>Provider subscription fees paid to Bookboll. Separate from academy fees and booking sales.</p></div><div><small>Received after refunds · matching listings</small><strong>{{ money(received) }}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Listing / business</th><th>Invoice</th><th>Paid on</th><th>Amount paid</th><th>Refunded</th><th>Status</th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id"><td>{{ i.listing }}<small>{{ i.business }}</small></td><td><a v-if="safeLink(i.hosted_invoice_url)" :href="i.hosted_invoice_url" target="_blank" rel="noopener">View invoice ↗</a><span v-else>{{ i.stripe_invoice_id }}</span></td><td>{{ date(i.paid_at) }}</td><td>{{ money(i.amount_paid) }}</td><td>{{ money(i.amount_refunded) }}</td><td>{{ i.status }}</td></tr><tr v-if="!invoices.length"><td colspan="6" class="ml-empty">Subscription invoices will appear here after Stripe confirms payment.</td></tr></tbody></table></div></section>
  </div>
  <Teleport to="body">
    <div v-if="editor" class="ml-overlay" @click.self="close"><section class="ml-dialog" v-dialog="close" role="dialog" aria-modal="true" aria-labelledby="ml-editor-title"><header><div><h2 id="ml-editor-title">{{ form.id ? 'Edit membership listing' : 'New membership listing' }}</h2><p>Customers contact the academy directly. Bookboll does not manage enrolment.</p></div><button class="btn btn-secondary btn-icon" aria-label="Close editor" @click="close"><X :size="18"/></button></header>
      <nav class="ml-tabs"><button :class="{active:editTab==='details'}" @click="editTab='details'">1. Listing details</button><button :class="{active:editTab==='placement'}" @click="editTab='placement'">2. Where it appears</button></nav>
      <form @submit.prevent="save(false)"><div class="ml-body">
        <div v-show="editTab==='details'" class="ml-fields"><label>Listing name *<input v-model="form.name" required maxlength="150" placeholder="e.g. Junior football academy"/></label><label>Venue *<select v-model="form.location_id" @change="chooseVenue"><option value="">Choose a venue</option><option v-for="v in venues" :value="String(v.id)" :key="v.id">{{ v.name }}</option></select></label><label class="ml-wide">Contact phone *<input v-model="form.contact_phone" type="tel" placeholder="Include country code, e.g. +974…" maxlength="40"/><small>Shown publicly so customers can call your academy.</small></label><label class="ml-wide">About this membership<textarea v-model="form.description" rows="4" placeholder="Who it’s for, what’s included and what customers should know."/></label><label>Sport<input v-model="form.sport_category" placeholder="e.g. Football"/></label><label>Category<select v-model="form.category"><option value="academy">Academy</option><option value="gym">Gym</option><option value="classes">Classes</option><option value="club">Club</option></select></label><label class="ml-wide">Schedule information<textarea v-model="form.schedule_description" rows="2" placeholder="e.g. Ages 8–12 · Sunday and Tuesday, 5–6pm"/><small>Information only. This does not reserve courts or create sessions.</small></label><label>Advertised academy price (optional)<input v-model="form.monthly_price" type="number" min="0" step="0.01"/><small>Leave 0 to show “Contact for pricing”.</small></label><div class="ml-fields"><label>Currency<input v-model="form.currency" maxlength="3"/></label><label>Per<select v-model="form.billing_interval"><option value="monthly">Month</option><option value="weekly">Week</option><option value="yearly">Year</option><option value="session">Session</option><option value="term">Term</option></select></label></div><label class="ml-wide">Cover image<input type="file" accept="image/*" :disabled="busy" @change="upload"/><img v-if="safeLink(form.photo_url)" :src="form.photo_url" class="ml-cover" alt="Listing cover preview"/></label></div>
        <div v-show="editTab==='placement'" class="ml-options"><section><Globe :size="24"/><div><h3>Bookboll marketplace</h3><p>{{ current ? money(current.listing_monthly_price) : 'Your venue’s monthly rate' }} per listing, billed monthly. Premium does not include this fee.</p><label><input type="checkbox" v-model="form.show_on_marketplace"/> Show on marketplace once approved and paid</label><small>Save first, then open View billing to subscribe. Saving this form never charges you.</small></div></section><section><Store :size="24"/><div><h3>Your branded website</h3><p>Available only while this business has an active Premium plan.</p><label><input type="checkbox" v-model="form.show_on_provider_site" :disabled="!websiteAllowed"/> Show on the business website</label><small v-if="!current">Save this listing to check the venue’s business plan.</small><small v-else-if="!websiteAllowed">Upgrade this business to Premium to enable this placement.</small><button v-if="current && !websiteAllowed" type="button" class="btn btn-secondary btn-sm" @click="openUpgrade('membership_website')">View Premium</button></div></section><p class="ml-notice">Hiding a listing does not cancel its subscription. Use View billing → Stop renewal to end monthly billing.</p></div>
        <p v-if="error" class="ml-error" role="alert">{{ error }}</p><div v-if="discard" class="ml-notice">Discard unsaved changes? <button type="button" class="btn btn-secondary btn-sm" @click="discard=false">Keep editing</button> <button type="button" class="btn btn-secondary btn-sm" @click="editor=false">Discard</button></div>
      </div><footer><button type="button" class="btn btn-secondary" :disabled="busy" @click="close">Cancel</button><div><button type="button" class="btn btn-secondary" :disabled="busy || !manage" @click="save(true)">Save draft</button><button type="button" v-if="editTab==='details'" class="btn btn-primary" @click="editTab='placement'">Continue</button><button v-else class="btn btn-primary" :disabled="busy || !manage">{{ busy ? 'Saving…' : 'Save listing' }}</button></div></footer></form>
    </section></div>
    <div v-if="selected" class="ml-overlay" @click.self="closeBilling"><section class="ml-dialog ml-small" v-dialog="closeBilling" role="dialog" aria-modal="true" aria-labelledby="ml-billing-title"><header><div><h2 id="ml-billing-title">{{ selected.name }}</h2><p>Marketplace subscription</p></div><button class="btn btn-secondary btn-icon" aria-label="Close billing" @click="closeBilling"><X :size="18"/></button></header><div class="ml-body">
      <p class="ml-price">{{ money(selected.listing_subscription?.amount ?? selected.listing_monthly_price) }} <small>/ listing / month</small></p><dl class="ml-summary"><div><dt>Marketplace</dt><dd>{{ status(selected) }}</dd></div><div><dt>Subscription</dt><dd>{{ selected.listing_subscription?.status || 'Not subscribed' }}</dd></div><div><dt>Paid through</dt><dd>{{ date(selected.listing_subscription?.paid_until) }}</dd></div><div><dt>Renewal</dt><dd>{{ selected.listing_subscription?.cancel_at_period_end ? 'Stops at period end' : selected.listing_subscription ? 'Monthly' : 'Starts after payment' }}</dd></div></dl>
      <p>This fee is paid to Bookboll for advertising this listing. Customers pay the academy directly for its services.</p><p v-if="!billingEnabled" class="ml-notice">{{ billingDisabledReason }}</p><p v-if="error" class="ml-error" role="alert">{{ error }}</p>
      <div v-if="manage" class="ml-billing-actions"><button v-if="!selected.listing_subscription || ['incomplete','incomplete_expired','canceled'].includes(selected.listing_subscription.status)" class="btn btn-primary" :disabled="busy || !billingEnabled || selected.is_draft || (selected.approval_status && selected.approval_status!=='approved') || ['paused','ineligible'].includes(selected.eligibility_status) || selected.status!=='active' || !selected.phone_ready" @click="confirmation='checkout'">Subscribe monthly ↗</button><template v-else><button class="btn btn-secondary" :disabled="busy || !billingEnabled" @click="billing('portal')">Invoices & payment method</button><button class="btn btn-secondary" :disabled="busy || !billingEnabled" @click="confirmation=selected.listing_subscription.cancel_at_period_end ? 'resume' : 'cancel'">{{ selected.listing_subscription.cancel_at_period_end ? 'Resume renewal' : 'Stop renewal' }}</button></template><button class="btn btn-secondary" :disabled="busy" @click="toggle(selected)">{{ selected.status==='active' ? 'Hide listing' : 'Activate listing' }}</button></div>
      <div v-if="confirmation" class="ml-notice"><strong>{{ confirmation === 'checkout' ? 'Start a recurring monthly subscription?' : confirmation === 'cancel' ? 'Stop renewal at the end of the paid period?' : 'Resume monthly renewal?' }}</strong><p>{{ confirmation === 'checkout' ? 'Review the amount and authorise payment securely with Stripe.' : 'The existing paid period remains available. Your Premium plan is unchanged.' }}</p><button class="btn btn-secondary btn-sm" :disabled="busy" @click="confirmation=null">Back</button> <button class="btn btn-primary btn-sm" :disabled="busy" @click="billing(confirmation)">Continue</button></div>
    </div></section></div>
  </Teleport>
</template>
<style scoped>
